import{_ as r,L as a,o as i,a as d,a7 as o,h as n}from"./chunks/framework.B-LquxkF.js";const c=JSON.parse('{"title":"第 1 章 人工智能基础理论","description":"","frontmatter":{},"headers":[],"relativePath":"ch01_ai_foundation.md","filePath":"ch01_ai_foundation.md"}'),e={name:"ch01_ai_foundation.md"};function u(s,t,h,q,g,b){const l=a("Compare");return i(),d("div",null,[t[0]||(t[0]=o('<h1 id="第-1-章-人工智能基础理论" tabindex="-1">第 1 章 人工智能基础理论 <a class="header-anchor" href="#第-1-章-人工智能基础理论" aria-label="Permalink to &quot;第 1 章 人工智能基础理论&quot;">​</a></h1><p>考核占比 30%，为五模块中占比最高。内容从经典机器学习延伸到大模型工程。</p><h2 id="_1-1-机器学习基础" tabindex="-1">1.1 机器学习基础 <a class="header-anchor" href="#_1-1-机器学习基础" aria-label="Permalink to &quot;1.1 机器学习基础&quot;">​</a></h2><p>本节回答四个递进问题：有哪些学习范式与算法、数据要如何处理与评估、神经网络如何学习、模型如何避免过拟合并选型。</p><h3 id="学习范式" tabindex="-1">学习范式 <a class="header-anchor" href="#学习范式" aria-label="Permalink to &quot;学习范式&quot;">​</a></h3><p><strong>解决什么问题</strong>：机器学习不靠显式规则编程，必须靠&quot;数据 + 学习目标&quot;驱动；范式不同，数据形式和学习目标就不同。</p><table tabindex="0"><thead><tr><th>范式</th><th>数据形式</th><th>学习目标</th><th>典型任务</th></tr></thead><tbody><tr><td>监督学习</td><td>输入样本加对应标签</td><td>学习输入到目标的映射</td><td>分类、回归</td></tr><tr><td>无监督学习</td><td>无标签数据</td><td>从数据中发现结构</td><td>聚类、降维</td></tr><tr><td>强化学习</td><td>环境交互反馈与奖励</td><td>学习最优策略</td><td>游戏、机器人控制</td></tr></tbody></table><ul><li>监督学习的训练数据必须包含目标标签，例如带&quot;垃圾邮件/正常邮件&quot;标签的历史邮件——标签提供&quot;正确答案&quot;，模型据此比对输出并修正</li><li>无监督学习从无标签数据中自动发现分组结构——没有标签，只能从数据分布本身找规律</li><li>强化学习根据环境反馈和奖励调整策略，奖励信号替代标签——没有现成答案，靠试错后的反馈学习</li></ul><h3 id="监督学习" tabindex="-1"><strong>监督学习</strong> <a class="header-anchor" href="#监督学习" aria-label="Permalink to &quot;**监督学习**&quot;">​</a></h3><blockquote><p>组织主线（高频）：监督学习按<strong>任务类型</strong>先分成<strong>回归</strong>（预测连续值）与<strong>分类</strong>（预测离散标签），但有的算法<strong>两者通用</strong>。六个经典算法先按任务归位，再逐个展开；这是选型与考试分类的第一把钥匙。</p></blockquote><p><strong>任务维度总览：六种算法归位</strong></p><table tabindex="0"><thead><tr><th>任务维度</th><th>算法</th><th>备注</th></tr></thead><tbody><tr><td>回归</td><td>线性回归</td><td>拟合连续值的线性模型，预测连续值</td></tr><tr><td>分类</td><td>逻辑回归</td><td>输出概率并按阈值分类</td></tr><tr><td>分类</td><td>支持向量机</td><td>画最大间隔边界分类</td></tr><tr><td>分类</td><td>朴素贝叶斯</td><td>按后验概率做分类，生成模型</td></tr><tr><td>两用</td><td>KNN</td><td>惰性，需特征缩放</td></tr><tr><td>两用</td><td>决策树</td><td>可解释、易过拟合，可集成</td></tr></tbody></table><blockquote><p>下面按&quot;由简到繁 + 成对对照&quot;展开各算法；每个小节都标注了它的任务归属，与上表一一对应。</p></blockquote><h3 id="线性回归与逻辑回归" tabindex="-1">线性回归与逻辑回归 <a class="header-anchor" href="#线性回归与逻辑回归" aria-label="Permalink to &quot;线性回归与逻辑回归&quot;">​</a></h3><blockquote><p>任务归属：线性回归 = <strong>回归</strong>；逻辑回归 = <strong>分类</strong>。二者都是最简单的线性监督模型，也是理解神经网络（多层线性组合 + 激活）的起点。</p></blockquote><ul><li>线性回归拟合连续值，模型为特征的线性组合，用梯度下降优化 MSE</li><li>逻辑回归输出经过 Sigmoid 映射的概率值，用于二分类</li><li>逻辑回归本质仍是线性模型，靠非线性激活输出概率</li><li>二者是最简单的监督模型，也是理解神经网络（多层线性组合加激活）的起点</li></ul><h3 id="knn" tabindex="-1">KNN <a class="header-anchor" href="#knn" aria-label="Permalink to &quot;KNN&quot;">​</a></h3><blockquote><p>任务归属：<strong>两用</strong>（常做分类，也可做回归）。</p></blockquote><p>KNN 是惰性算法，新样本到来时计算其与训练集样本的距离，取最近的 K 个样本按多数投票决定类别。</p><ul><li>距离计算对每个特征维度同等加权</li><li>特征取值范围差异大时，大尺度特征在距离计算中占主导地位</li><li>使用 KNN 前需对特征做缩放，把各维度拉回相近量级</li><li>特征缩放本质是数据预处理（详见下节&quot;数据标准化与归一化&quot;），KNN、SVM 这类基于距离的算法尤其依赖它</li></ul><h3 id="决策树与集成学习" tabindex="-1">决策树与集成学习 <a class="header-anchor" href="#决策树与集成学习" aria-label="Permalink to &quot;决策树与集成学习&quot;">​</a></h3><blockquote><p>任务归属：决策树 <strong>两用</strong>（分类树 / 回归树皆有）；本节主题是个体（决策树）与群体（集成学习）的关系。 本节回答：为什么单个模型要&quot;一组&quot;才强？为什么集成学习总把决策树当零件？</p></blockquote><ul><li><strong>决策树是基学习器</strong>：一个<strong>具体的分类/回归模型</strong>，按特征条件逐层划分样本，可解释性强</li><li><strong>集成学习是组合策略</strong>：一种<strong>把个体装配成群体</strong>的方式，把多个弱模型组合成强模型</li><li>二者不是并列概念，而是&quot;零件&quot;与&quot;装配工艺&quot;的关系：集成学习最经典的基学习器恰是决策树，而决策树又恰好有集成能修的弱点——天然互补</li></ul><h4 id="_1-决策树" tabindex="-1"><strong>1 决策树</strong> <a class="header-anchor" href="#_1-决策树" aria-label="Permalink to &quot;**1 决策树**&quot;">​</a></h4><ul><li>决策树按特征条件逐层划分样本，可解释性强，但<strong>容易过拟合</strong>（高方差、对训练数据太敏感）</li><li>单棵树的短处正是集成的用武之地：<strong>个体有方差，就用群体去摊平</strong></li></ul><h4 id="_2-集成学习" tabindex="-1"><strong>2 集成学习</strong> <a class="header-anchor" href="#_2-集成学习" aria-label="Permalink to &quot;**2 集成学习**&quot;">​</a></h4><ul><li><p>弱模型指精度只略高于随机猜测的模型，集成后整体变强</p></li><li><p>两种主流组合方式：</p><ul><li><strong>Bagging</strong>（并行、各自独立、投票/平均）</li><li><strong>Boosting</strong>（串行、逐步补差）</li></ul></li><li><p>优化方向：Bagging 靠&quot;平均&quot;降<strong>方差</strong>（压制过拟合）；Boosting 靠&quot;修正&quot;降<strong>偏差</strong>（提升精度）</p><ul><li><p><strong>1 随机森林（基于Bagging + 决策树）：靠&quot;平均&quot;降方差</strong></p><p>由多棵决策树组成，每棵树用随机子集训练，投票输出结果，降低过拟合——多棵树的结果平均化，能摊平单棵的过拟合（降方差）</p></li><li><p><strong>2 梯度提升树 GBDT（基于Boosting + 决策树）：靠&quot;修正&quot;降偏差</strong></p><p>GBDT 逐棵树拟合前序残差，拟合残差本质是沿&quot;损失下降方向&quot;做梯度下降，只是用树去拟合这个方向，代表有 XGBoost；每棵新树都补上一棵的短板，所以整体精度被逐轮推高</p><p>Tips：<strong>残差（Residual）：GBDT 到底在&quot;补&quot;什么</strong></p><blockquote><p>上面说 GBDT&quot;逐棵树拟合前序残差&quot;</p></blockquote><ul><li>残差 = <strong>真实值 − 当前模型的预测值</strong>，即&quot;模型还没拟合好的剩余误差&quot;</li><li>例子：预测房价，第一棵树预测 100 万、真实 150 万，残差 = 150 − 100 = <strong>+50 万</strong>；第二棵树不直接学&quot;房价&quot;，而学<strong>这个 +50 万的缺口</strong>，把预测补到 150 万；若还差 5 万，第三棵树学 +5 万……逐轮逼近真实值</li><li>每棵新树只负责<strong>纠正前面的错误</strong>，整体越来越贴近真实——这就是 boosting（提升）：串行、后一棵补前一棵的短板</li></ul><p><strong>为什么&quot;拟合残差&quot;就是梯度下降</strong></p><ul><li>以平方误差损失为例，它对预测值的梯度正比于（预测 − 真实），方向与残差一致；所以&quot;让树去拟合残差&quot;= 沿<strong>损失下降方向</strong>走一步，只是用树这个模型表达&quot;该往哪走、走多少&quot;</li><li>于是 GBDT 不是&quot;再学一个独立模型&quot;，而是&quot;每学一棵都给损失的下降补一刀&quot;</li></ul></li></ul><p><strong>随机森林 vs GBDT</strong></p><table tabindex="0"><thead><tr><th>集成</th><th>建树方式</th><th>各树关系</th><th>目标</th></tr></thead><tbody><tr><td>随机森林</td><td>并行，各树独立</td><td>结果投票/平均</td><td>降方差、压制过拟合</td></tr><tr><td>GBDT</td><td>串行，逐步推进</td><td>后一棵拟合前一棵残差</td><td>降偏差、提升精度</td></tr></tbody></table></li></ul><h3 id="支持向量机与朴素贝叶斯" tabindex="-1">支持向量机与朴素贝叶斯 <a class="header-anchor" href="#支持向量机与朴素贝叶斯" aria-label="Permalink to &quot;支持向量机与朴素贝叶斯&quot;">​</a></h3><blockquote><p>任务归属：两者均为 <strong>分类</strong>。本节按&quot;分类的两条路&quot;讲：SVM 从几何入手<strong>画边界</strong>，朴素贝叶斯从概率入手<strong>算后验</strong>——同是分类，走法截然不同。先各自讲透&quot;想解决什么 → 核心机制 → 怎么算 → 适用与边界&quot;，最后对比收束。</p></blockquote><p><strong>先看共同的起点：分类算法</strong></p>',30)),n(l,{data:'{"columns":["SVM","朴素贝叶斯"],"rows":[{"dim":"派别","cells":["判别模型·画边界","生成模型·算概率"]},{"dim":"入手点","cells":["几何间隔","概率后验"]},{"dim":"自信依据","cells":["间隔距离","概率置信度"]}]}',title:"判别 vs 生成：分类的两条路"}),t[1]||(t[1]=o('<ul><li><strong>判别派（SVM）</strong>：不问数据怎么来的，直接找一条分界线，照着切。</li><li><strong>生成派（朴素贝叶斯）</strong>：先学&quot;每一类数据长什么样&quot;，再看新样本更像哪一类，用概率判断。</li></ul><h4 id="_1-svm-用-最大间隔-找最稳的分界线" tabindex="-1">1. SVM：用&quot;最大间隔&quot;找最稳的分界线 <a class="header-anchor" href="#_1-svm-用-最大间隔-找最稳的分界线" aria-label="Permalink to &quot;1. SVM：用&quot;最大间隔&quot;找最稳的分界线&quot;">​</a></h4><ul><li>能分开两类的直线有无穷多条，SVM 要挑<strong>最稳</strong>的那条：到两侧最近样本的距离（间隔）最大。间隔越大，数据轻微扰动也不易分错，对新样本更抗造。</li></ul><p><strong>核心机制：间隔 + 支持向量</strong></p><ul><li><strong>间隔</strong>：分类线到两侧最近样本的距离，越大越稳。</li><li><strong>支持向量</strong>：真正&quot;顶着&quot;间隔边界的少数样本。只有它们决定这条线，其余样本只要不越界、动一动都不影响结果 → 模型稀疏，只记住关键样本。</li></ul><p><strong>怎么算：把&quot;最大间隔&quot;变成可解的问题</strong></p><ul><li>最大化间隔 = 最小化 ‖w‖²，是一个<strong>凸二次规划</strong>问题。凸问题只有全局最优、不会掉进局部最优</li></ul><p><strong>数据不干净或分不开时的两个升级</strong></p><ul><li><strong>软间隔</strong>：允许少量样本越过边界，用惩罚参数 C 平衡&quot;分得对&quot;与&quot;间隔大&quot;。C 大 → 偏严格（易过拟合），C 小 → 偏平滑。</li><li><strong>核技巧</strong>：线性分不开时，把数据映射到高维再切；核函数直接算高维内积、不必真做映射，RBF 高斯核最常用（相当于无穷维特征空间）。</li></ul><p><strong>适用与边界</strong></p><ul><li><strong>适合高维小样本</strong>：模型复杂度由支持向量数决定、而非特征维度——文本、基因这类&quot;特征多、样本少&quot;的数据尤其合适。</li><li><strong>对尺度敏感</strong>：SVM 依赖距离/内积，用前要做特征标准化（呼应上文 KNN）。</li></ul><h4 id="_2-朴素贝叶斯-用-条件独立-把概率算到底" tabindex="-1">2. 朴素贝叶斯：用&quot;条件独立&quot;把概率算到底 <a class="header-anchor" href="#_2-朴素贝叶斯-用-条件独立-把概率算到底" aria-label="Permalink to &quot;2. 朴素贝叶斯：用&quot;条件独立&quot;把概率算到底&quot;">​</a></h4><ul><li>类别并不确定，那就把&quot;属于每一类&quot;的概率都算出来，取<strong>概率最大</strong>者。</li></ul><p><strong>核心机制：贝叶斯定理</strong></p><ul><li>后验概率 ∝ <strong>先验概率 × 似然</strong>： <ul><li>先验：某类别在数据里占的比例。</li><li>似然：在该类别出现的情况下，看到这组特征的概率。</li></ul></li><li>预测时对每个类别算后验，取最大者。</li></ul><p><strong>&quot;朴素&quot;：条件独立</strong></p><ul><li>假定各特征<strong>条件独立</strong>，把复杂的联合概率拆成&quot;每个特征单独概率&quot;的乘积。否则要估计特征组合的联合分布，数据需求随特征数<strong>指数级</strong>增长，实际根本估不准。假设虽&quot;朴素&quot;，却让计算可行。</li><li>代价：训练退化成&quot;数数&quot;——统计先验与各特征条件概率即可，<strong>极快、可增量更新</strong>。</li></ul><p><strong>适用与边界</strong></p><ul><li><strong>常用于文本分类</strong>（垃圾邮件、情感分析）：把文档看成词频组合，正好契合&quot;词与词独立&quot;的假设。</li><li>输出概率而非裸类别，天然带置信度，方便跟其他系统结合。</li></ul><h4 id="_3-对比" tabindex="-1">3. 对比 <a class="header-anchor" href="#_3-对比" aria-label="Permalink to &quot;3. 对比&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>支持向量机</th><th>朴素贝叶斯</th></tr></thead><tbody><tr><td>派别</td><td>判别模型（画边界）</td><td>生成模型（算概率）</td></tr><tr><td>入手点</td><td>几何间隔</td><td>概率后验</td></tr><tr><td>自信依据</td><td>间隔距离</td><td>概率置信度</td></tr><tr><td>数据需求</td><td>高维小样本</td><td>只需统计频率、极快</td></tr><tr><td>特征假设</td><td>无所假设（靠核技巧）</td><td>条件独立</td></tr><tr><td>尺度</td><td>需标准化</td><td>相对不敏感</td></tr></tbody></table><h3 id="判别模型与生成模型-概念辨析" tabindex="-1"><strong>判别模型与生成模型（概念辨析）</strong> <a class="header-anchor" href="#判别模型与生成模型-概念辨析" aria-label="Permalink to &quot;**判别模型与生成模型（概念辨析）**&quot;">​</a></h3><blockquote><p>本节解决：SVM 与朴素贝叶斯只是两个具体算法，背后其实是<strong>机器学习模型的两大派别</strong>——判别模型与生成模型。分清这对概念，才能理解&quot;为什么有的模型只给分类边界、有的模型还能生成新样本&quot;。</p></blockquote><p><strong>一行区分</strong></p><ul><li><strong>判别模型（Discriminative Model）</strong>：直接学&quot;<strong>怎么分</strong>&quot;——给定输入 x，学一个分界线或条件概率 P(y|x)，<strong>不关心数据是怎么来的</strong>。只管把这张图分对。</li><li><strong>生成模型（Generative Model）</strong>：先学&quot;<strong>数据怎么来的</strong>&quot;——学输入和标签的联合分布 P(x,y)，理解了每类数据&quot;长什么样&quot;，再由此推后验 P(y|x)。既能分类，也能<strong>生成新样本</strong>。</li></ul><p><strong>核心机制：一个学条件分布，一个学联合分布</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>判别模型</th><th>生成模型</th></tr></thead><tbody><tr><td>建模对象</td><td>条件分布 P(y|x) 或决策边界</td><td>联合分布 P(x, y)</td></tr><tr><td>关心什么</td><td>把输入映射到哪一类</td><td>数据是如何生成的</td></tr><tr><td>不关心什么</td><td>数据本身的分布形状</td><td>决策边界的形状</td></tr><tr><td>能否生成新样本</td><td>一般不能</td><td>能（采样出新的 x）</td></tr><tr><td>代表算法</td><td>逻辑回归、SVM、决策树、随机森林、神经网络</td><td>朴素贝叶斯、高斯混合模型 GMM、隐马尔可夫 HMM、GAN、VAE、扩散模型</td></tr><tr><td>典型任务</td><td>分类、回归</td><td>生成、聚类、分类、降维、缺失补全</td></tr></tbody></table><p><strong>为什么判别模型通常&quot;分类性能更好&quot;</strong></p><ul><li>判别模型<strong>只把精力花在&quot;分对&quot;这件事上</strong>，不浪费算力去建模数据的完整分布；在分类任务上，往往用更少的样本就能把边界学准。</li><li>生成模型为了&quot;理解数据怎么来的&quot;，要把整个 P(x,y) 建出来，<strong>建模难度更高、需要更多数据</strong>；好处是换来&quot;生成 + 推理数据生成过程&quot;的能力。</li></ul><p><strong>为什么生成模型&quot;更全能但更难&quot;</strong></p><ul><li>一旦有了联合分布，<strong>不仅能分类，还能生成</strong>：向 P(x) 采样即可造出新的样本（GAN/VAE/扩散模型靠这个）。</li><li>还能处理<strong>缺失数据、无监督聚类、异常检测</strong>，并给出更&quot;解释性&quot;的答案（知道每类长什么样）。</li><li>代价：高维数据的联合分布极难精确建模，需要大量数据与复杂模型，训练也更不稳定。</li></ul><p><strong>生成模型靠什么生成新样本（延伸）</strong></p><ul><li>学习到&quot;每类数据服从什么分布&quot;后，<strong>从该分布里采样</strong>就能得到这个类的&quot;新样本&quot;。</li><li>代表：</li></ul><table tabindex="0"><thead><tr><th>模型</th><th>生成方式</th></tr></thead><tbody><tr><td>朴素贝叶斯</td><td>学了每类特征的概率，可生成&quot;某类下的样本&quot;</td></tr><tr><td>GMM 高斯混合模型</td><td>学多个高斯分量，从对应分量采样</td></tr><tr><td>GAN</td><td>生成器 + 判别器对抗，生成器学&quot;造得像真的&quot;</td></tr><tr><td>VAE</td><td>学潜在编码分布，解码还原生成</td></tr><tr><td>扩散模型</td><td>从噪声逐步去噪，还原出图像</td></tr></tbody></table><p><strong>高频辨析（判定口诀）</strong></p><ul><li><strong>看它学的是&quot;边界&quot;还是&quot;分布&quot;</strong>：只求边界不求分布 → 判别；既求分布又能生成 → 生成。</li><li><strong>能否生成新样本</strong>：能生成 → 生成模型；只做分类/回归 → 判别模型。</li><li><strong>注意：一个任务可能用两类模型都行</strong>——分类可以用判别模型（SVM）也可以用生成模型（朴素贝叶斯），所以&quot;判别/生成&quot;指的是模型<strong>学什么</strong>，而不是任务本身。</li><li><strong>高频误区</strong>：&quot;生成模型只能做生成&quot;——错，生成模型同样可做分类（朴素贝叶斯就是分类）；&quot;判别模型不能解释数据&quot;——大致成立，因为它没建数据分布，也就讲不清数据怎么来的。</li></ul><p><strong>衔接</strong>：SVM（判别）与朴素贝叶斯（生成）正是这两个派别的典型代表；而 1.6 的多模态、以及 GAN/VAE（见神经网络分类表），则是生成模型在&quot;造数据&quot;方向的延伸。</p><h3 id="非监督学习" tabindex="-1"><strong>非监督学习</strong> <a class="header-anchor" href="#非监督学习" aria-label="Permalink to &quot;**非监督学习**&quot;">​</a></h3><h3 id="聚类与降维" tabindex="-1">聚类与降维 <a class="header-anchor" href="#聚类与降维" aria-label="Permalink to &quot;聚类与降维&quot;">​</a></h3><ul><li>K-means 把样本分成 K 簇，迭代更新簇中心，样本归入最近簇；需要预先指定簇数 K，对初始中心敏感</li><li>PCA 主成分分析把高维数据投影到方差最大的方向上，实现降维；降维保留主要信息的同时降低计算量，常作为预处理步骤</li></ul><h3 id="数据预处理" tabindex="-1"><strong>数据预处理</strong> <a class="header-anchor" href="#数据预处理" aria-label="Permalink to &quot;**数据预处理**&quot;">​</a></h3><h3 id="数据标准化与归一化" tabindex="-1">数据标准化与归一化 <a class="header-anchor" href="#数据标准化与归一化" aria-label="Permalink to &quot;数据标准化与归一化&quot;">​</a></h3><ul><li>标准化 z-score 减去均值除以标准差，处理后均值为0，方差为 1；按列处理，样本本身的值仍各不相同</li><li>归一化把数值映射到固定区间，例如 0 到 1</li></ul><p>两种方式都把不同量纲的特征调整到更可比较的尺度，因为量纲差异会干扰基于距离和梯度的学习算法（如，KNN、SVM 对缩放的依赖）</p><h3 id="数据集划分" tabindex="-1">数据集划分 <a class="header-anchor" href="#数据集划分" aria-label="Permalink to &quot;数据集划分&quot;">​</a></h3><ul><li>数据划分为训练集、验证集、测试集；训练集用于更新参数，验证集用于调参和模型选择，测试集用于最终评估</li></ul><h3 id="数据评估指标" tabindex="-1"><strong>数据评估指标</strong> <a class="header-anchor" href="#数据评估指标" aria-label="Permalink to &quot;**数据评估指标**&quot;">​</a></h3><ul><li>回归评估常用 均方误差MSE、平均绝对误差MAE</li><li>分类评估常用准确率、精确率、召回率、F1 <ul><li>精确率衡量预测为正类的样本中预测正确的比例</li><li>召回率衡量真实正类中被正确找出的比例</li><li>F1 是精确率和召回率的调和平均——两者往往此消彼长（如&quot;宁错报也别漏报&quot;时看召回率），调和平均能同时惩罚两者的不足</li><li>混淆矩阵列出预测与真实的各种组合，是精确率和召回率的计算基础</li></ul></li></ul><h3 id="神经网络及其优化" tabindex="-1"><strong>神经网络及其优化</strong> <a class="header-anchor" href="#神经网络及其优化" aria-label="Permalink to &quot;**神经网络及其优化**&quot;">​</a></h3><h3 id="神经网络基础" tabindex="-1">神经网络基础 <a class="header-anchor" href="#神经网络基础" aria-label="Permalink to &quot;神经网络基础&quot;">​</a></h3><p>神经元对输入加权求和加偏置，经激活函数输出</p><ul><li><strong>偏置 bias（b）</strong>：在加权和上再加一个常数，即 z = Σ(wᵢ·xᵢ) + b，再送入激活函数</li><li><strong>为什么需要偏置</strong>： <ul><li>对照直线 y = wx + b：<strong>权重 w 定&quot;斜率/方向&quot;，偏置 b 定&quot;截距/平移&quot;</strong>——没有 b，直线只能过原点</li><li>对神经元同理：<strong>没有偏置</strong>时，当所有输入为 0，加权和恒为 0，输出被固定在激活函数的某个点，模型表达不了&quot;输入为 0 也应输出特定值&quot;的规律，决策边界被限制在&quot;过原点&quot;</li><li>有了偏置，神经元才能<strong>平移激活函数与决策边界</strong>、拟合不过原点的规律——表达能力更强</li></ul></li><li>多层网络靠激活函数引入非线性，完全线性的多层叠加仍是线性变换</li></ul><p>前向传播逐层计算输出，反向传播沿计算图回传梯度</p><h4 id="神经网络分类" tabindex="-1">神经网络分类 <a class="header-anchor" href="#神经网络分类" aria-label="Permalink to &quot;神经网络分类&quot;">​</a></h4><p>按&quot;核心结构 + 擅长数据&quot;分，常见类别如下：</p><table tabindex="0"><thead><tr><th>类别</th><th>核心机制</th><th>擅长数据</th><th>代表 / 衍生</th></tr></thead><tbody><tr><td>前馈网络 / MLP</td><td>全连接，逐层非线性变换</td><td>通用分类、回归</td><td>多层感知机（基础模型）</td></tr><tr><td>卷积神经网络 CNN</td><td>卷积核提取局部特征 + 池化降维，权值共享、参数少</td><td>图像、空间数据</td><td>LeNet、ResNet</td></tr><tr><td>循环神经网络 RNN</td><td>按序列顺序循环处理，保留上一时刻状态</td><td>文本、时间序列</td><td>LSTM、GRU（缓解长序列梯度消失）</td></tr><tr><td>Transformer</td><td>自注意力并行处理整段序列、捕获长距离依赖</td><td>文本、序列（LLM 的基石）</td><td>GPT、BERT</td></tr><tr><td>生成对抗网络 GAN</td><td>生成器与判别器对抗训练</td><td>图像生成、风格迁移</td><td>DCGAN、StyleGAN</td></tr><tr><td>自编码器 AE / VAE</td><td>压缩-重构，无监督学隐含表征</td><td>降维、去噪、生成</td><td>变分自编码器 VAE</td></tr><tr><td>图神经网络 GNN</td><td>图中节点聚合邻居特征</td><td>社交网络、分子结构</td><td>GCN、GAT</td></tr></tbody></table><ul><li><strong>CNN 适合图像</strong>：卷积核在局部窗口共享权重，天然捕捉平移不变的局部纹理；池化再降尺度、增大感受野——比全连接参数省得多。</li><li><strong>RNN 适合序列</strong>：它按顺序&quot;接力&quot;处理，前一时刻的隐藏状态带回下一时刻，天然建模先后依赖；但长序列梯度容易在逐层乘法中消失，LSTM/GRU 用门控让信息能&quot;存下来&quot;。</li><li><strong>Transformer 后来居上</strong>：自注意力让每个位置都能直接看全序列（不再逐字接力），可并行训练，反而更擅长长距离依赖。</li><li><strong>另一维度：按学习方式</strong>——监督（MLP、CNN、RNN 多用于分类/回归）、无监督（AE、GAN 学数据分布、可生成）、强化（DQN 等用于决策）；其中&quot;判别 vs 生成&quot;的完整概念见上文「判别模型与生成模型（概念辨析）」，此处恰好呼应 SVM（判别）与朴素贝叶斯（生成）的对照。</li></ul><h3 id="损失函数" tabindex="-1">损失函数 <a class="header-anchor" href="#损失函数" aria-label="Permalink to &quot;损失函数&quot;">​</a></h3><p>损失函数衡量模型预测与真实值的差距，训练过程即最小化损失。</p><ul><li>回归任务常用均方误差 MSE，计算预测值与真实值差值的平方均值</li><li>分类任务常用交叉熵损失，衡量预测概率分布与真实分布的差异</li><li>损失越小，模型输出与真实值越接近</li><li>没有损失函数就无从量化误差，也就没有优化的方向</li></ul><h3 id="梯度下降与学习率" tabindex="-1">梯度下降与学习率 <a class="header-anchor" href="#梯度下降与学习率" aria-label="Permalink to &quot;梯度下降与学习率&quot;">​</a></h3><p>训练目标是让损失函数 L 取最小值。参数 θ 沿损失下降最快的方向逐步更新，更新规则为 θ ← θ − η·∇L，其中 ∇L 是损失对参数的梯度，η 是学习率。</p><ul><li>梯度反映损失函数对参数变化的方向与敏感程度，指向损失上升最快的方向，负梯度即下降方向</li><li>为什么能收敛：损失面在一阶近似下，沿负梯度方向损失单调下降，逐步逼近极小值点</li><li>学习率过大时参数跨过最优点来回震荡，训练损失发散——步长超过损失面曲率允许的范围，就会&quot;跳过&quot;谷底</li><li>学习率过小则收敛缓慢</li><li>优化器基于梯度更新参数，SGD 每次用一个小批量估计梯度，Momentum 累积历史梯度冲量缓解震荡，Adam 自适应调整每个参数的学习率</li></ul><h3 id="控制模型过度泛化" tabindex="-1"><strong>控制模型过度泛化</strong> <a class="header-anchor" href="#控制模型过度泛化" aria-label="Permalink to &quot;**控制模型过度泛化**&quot;">​</a></h3><h3 id="过拟合与正则化" tabindex="-1">过拟合与正则化 <a class="header-anchor" href="#过拟合与正则化" aria-label="Permalink to &quot;过拟合与正则化&quot;">​</a></h3><p>过拟合指模型在训练集上表现好、在测试集上表现差，原因是模型记住了训练数据的噪声。</p><ul><li>特征过多、模型复杂度过高、训练数据过少都会引发过拟合</li><li>正则化在损失函数上增加参数惩罚，L1 使权重稀疏，L2 使权重整体变小——L1 在零点附近梯度恒定，推动权重精确归零；L2 梯度随权重线性缩小，只能压小不能归零</li><li>Dropout 在训练时随机丢弃部分神经元，防止网络过度依赖某些节点</li><li>早停观察验证集表现，在验证集开始变差时停止训练</li><li>数据增强增加训练样本多样性</li></ul><h3 id="偏差与方差" tabindex="-1">偏差与方差 <a class="header-anchor" href="#偏差与方差" aria-label="Permalink to &quot;偏差与方差&quot;">​</a></h3><ul><li>偏差衡量模型预测的平均偏离程度，高偏差对应欠拟合</li><li>方差衡量模型对训练数据变化的敏感程度，高方差对应过拟合</li><li>模型复杂度增加，偏差下降、方差上升，需要平衡——复杂度越高拟合能力越强（偏差降），但对训练数据的微小波动越敏感（方差升）</li><li>偏差与方差是&quot;过拟合/欠拟合&quot;的两种表现，与评估指标共同回答&quot;模型好不好&quot;</li></ul><h3 id="机器学习算法选择因素" tabindex="-1">机器学习算法选择因素 <a class="header-anchor" href="#机器学习算法选择因素" aria-label="Permalink to &quot;机器学习算法选择因素&quot;">​</a></h3><p>选算法先看任务、数据、可解释性与资源四类约束，再考虑细节：</p><ul><li>任务类型：分类还是回归</li><li>数据规模与特征类型：样本量、特征维度与尺度——高维小样本适合 SVM；KNN/SVM 对特征尺度敏感，需先缩放</li><li><strong>可解释性要求</strong>（见下）</li><li>训练和推理资源：算力、内存、推理时延——资源紧可选朴素贝叶斯（训练极快、可增量更新）</li><li>数据质量：噪声、缺失、类别不平衡——有噪声时用软间隔 SVM、随机森林摊平过拟合</li><li>过拟合风险：特征多、样本少时选简单模型并配合正则化</li><li>非线性需求：数据线性可分吗，不可分→核技巧（SVM）或树模型</li></ul><p><strong>可解释性要求是什么</strong>：模型能否对&quot;为什么这样判断&quot;给出人能看懂的理由。</p><ul><li>白盒（可解释）：决策树能直接看出按什么特征、什么阈值逐层划分；线性回归/逻辑回归能看出每个特征贡献多大</li><li>黑盒（难解释）：深度神经网络、随机森林等只给结果、说不清理由 <ul><li>为什么重要：医疗诊断、金融信贷、司法风控等高风险场景必须能向用户与监管解释，否则不可用；可解释还有助调试排错、审查偏见</li><li>取舍：可解释性与精度常此消彼长——要求高选决策树/线性模型，追求精度选集成树/深度学习，折中用 LIME、SHAP 做事后解释</li></ul></li></ul><h2 id="_1-2-大语言模型原理" tabindex="-1">1.2 大语言模型原理 <a class="header-anchor" href="#_1-2-大语言模型原理" aria-label="Permalink to &quot;1.2 大语言模型原理&quot;">​</a></h2><p>大语言模型的完整原理（Token / Embedding / Transformer 架构 / 位置编码 / 自回归与训练三阶段 / 注意力变体与 KV Cache / 上下文窗口 / Scaling Laws / 幻觉）已移至第 4 章 4.2，从 Agent 视角统一讲解、与能力边界对照。本节保留模型层面需单独细化的矩阵级推导。</p><blockquote><p>注意力变体（MHA / MQA / GQA / MLA）的完整讲解、MHA 矩阵级推导与 MLA 压缩细节，已**并入第 4 章 §4.2「注意力变体与 KV Cache」**的演进主线（含四种变体列表比较）。本节不再重复。</p></blockquote><h2 id="_1-3-推理与采样" tabindex="-1">1.3 推理与采样 <a class="header-anchor" href="#_1-3-推理与采样" aria-label="Permalink to &quot;1.3 推理与采样&quot;">​</a></h2><p>承接 4.2：自回归生成中，模型每一步输出的不是唯一答案，而是词表上的概率分布。本节回答&quot;如何从概率分布中选词、如何控制生成&quot;。</p><h3 id="解码策略" tabindex="-1">解码策略 <a class="header-anchor" href="#解码策略" aria-label="Permalink to &quot;解码策略&quot;">​</a></h3><p>模型每步输出词表上的概率分布，解码策略决定如何选取下一个 Token。</p><table tabindex="0"><thead><tr><th>策略</th><th>机制</th><th>特点</th></tr></thead><tbody><tr><td>贪心解码</td><td>每次取概率最高的 Token</td><td>结果确定，可能重复单调</td></tr><tr><td>温度采样</td><td>按温度缩放概率分布后随机采样</td><td>温度低更确定，温度高更随机</td></tr><tr><td>Top-k 采样</td><td>固定保留概率最高的前 K 个候选再采样</td><td>候选数固定</td></tr><tr><td>Top-p 采样</td><td>按累计概率阈值动态选取候选集合再采样</td><td>候选数随分布变化</td></tr></tbody></table><p><strong>采样参数是什么</strong>：模型只产出概率分布、不决定具体选哪个词；采样参数就是控制&quot;如何从分布中挑出下一个 Token&quot;的旋钮，推理时设置、不改模型权重。解码策略是选词方法（贪心、温度、Top-k、Top-p），采样参数是这些方法的数值配置（temperature、top_k、top_p 等）。</p><ul><li>Top-k 的 K 是固定值，例如保留前 50 个候选，即可top_k=50</li><li>Top-p 从概率最高的 Token 开始累加，直到累计概率达到阈值，例如 top_p=0.9，候选集合大小每一步都可能不同</li><li>温度大于 1 使分布更平滑随机，小于 1 使分布更尖锐确定——机制：先对 logits 除以温度再 Softmax，高温把差距抹平（更随机），低温把差距放大（更确定）</li><li>贪心解码永远选最高概率，容易陷入局部最优而重复单调，采样类策略用随机性破局</li><li>生成行为同时受采样参数、上下文窗口、Prompt 内容和模型能力影响</li></ul><h3 id="影响一次性生成行为的因素" tabindex="-1">影响一次性生成行为的因素 <a class="header-anchor" href="#影响一次性生成行为的因素" aria-label="Permalink to &quot;影响一次性生成行为的因素&quot;">​</a></h3><p>模型每步输出概率分布，最终输出由&quot;能看什么、输入什么、会什么、怎么选&quot;四层共同决定：</p><table tabindex="0"><thead><tr><th>因素</th><th>影响方式</th></tr></thead><tbody><tr><td>上下文窗口</td><td>决定模型能&quot;看到&quot;多少历史，超窗信息不参与本次生成</td></tr><tr><td>Prompt 内容</td><td>决定条件概率的起点，是本次生成的输入</td></tr><tr><td>模型能力</td><td>训练得到的知识与模式，决定概率分布本身</td></tr><tr><td>采样参数</td><td>决定从分布中如何选词，不改模型权重、推理时可调</td></tr></tbody></table><ul><li>同一个 prompt + 同一个模型，采样参数不同 → 输出可能不同</li><li>采样参数是解码策略的&quot;具体配置&quot;：解码策略是选词方法（贪心、温度、Top-k、Top-p），采样参数是这些方法的数值旋钮（temperature=0.7、top_p=0.9、top_k=50）</li><li>因果链：窗口 / Prompt / 能力决定&quot;有哪些候选&quot;，采样参数决定&quot;选哪个&quot;</li></ul><h3 id="生成控制" tabindex="-1">生成控制 <a class="header-anchor" href="#生成控制" aria-label="Permalink to &quot;生成控制&quot;">​</a></h3><ul><li>最大生成 Token 数限制输出长度</li><li>重复惩罚降低已出现 Token 的概率，抑制重复</li><li>停止符让模型在特定 Token 处结束生成</li></ul><p><strong>小结</strong>：采样决定&quot;生成什么&quot;。而模型能否真正落地，还取决于它的规模成本与部署优化——进入模型工程。</p><h2 id="_1-4-模型优化与工程" tabindex="-1">1.4 模型优化与工程 <a class="header-anchor" href="#_1-4-模型优化与工程" aria-label="Permalink to &quot;1.4 模型优化与工程&quot;">​</a></h2><p>模型规模大，训练和部署成本高。本节回答&quot;如何降本、如何落地&quot;，主线为：训练侧降本（微调）→ 部署侧降本（量化）→ 资源度量（精度与显存）→ 部署引擎 → 多卡并行 → 架构侧降本（MoE）。</p><h3 id="微调方式" tabindex="-1">微调方式 <a class="header-anchor" href="#微调方式" aria-label="Permalink to &quot;微调方式&quot;">​</a></h3><ul><li>全量微调更新全部参数，算力和显存开销大</li><li>SFT 使用带指令或示例的监督数据微调模型</li><li>LoRA 冻结原始权重，只训练低秩分解矩阵，参数量减少到 0.1%~1%——为什么有效：微调对权重的更新量往往是低秩的，用低秩矩阵近似即可表达大部分调整</li><li>QLoRA 在 LoRA 基础上把基座权重量化，进一步降低显存</li><li>PEFT 类方法大幅降低微调的显存和算力需求，适合算力受限场景</li></ul><p><strong>微调降低&quot;训练成本&quot;；部署时还要压缩体积、加快推理——量化。</strong></p><h3 id="量化" tabindex="-1">量化 <a class="header-anchor" href="#量化" aria-label="Permalink to &quot;量化&quot;">​</a></h3><p>量化把高精度浮点权重映射到低精度整数，压缩模型体积。权重从 FP16 量化为 INT8，每个参数从 2 字节降到 1 字节，显存占用减少约一半。</p><ul><li>常见量化方式有 GPTQ、AWQ、INT8、INT4</li><li>量化降低模型存储和推理资源需求</li><li>INT8 推理相比 FP32 吞吐提升约 4 倍，精度影响小</li><li>量化越激进，精度损失越大，需要权衡——为什么损精度：低精度表示把连续浮点值离散到有限整数刻度，产生量化误差；位数越少误差越大</li><li>为什么更快：位宽减半，同样带宽下数据搬运量减半，计算单元单位时间可处理更多数据</li></ul><h3 id="精度与显存" tabindex="-1">精度与显存 <a class="header-anchor" href="#精度与显存" aria-label="Permalink to &quot;精度与显存&quot;">​</a></h3><ul><li>FP32 每个数占 4 字节，FP16 占 2 字节，BF16 同为 2 字节但数值范围更大</li><li>FP16 显存占用减半、计算吞吐翻倍——位宽减半，数据量减半，吞吐随之翻倍</li><li>混合精度训练中权重以 FP32 存储、前向反向计算用 FP16、梯度累加用 FP32 更新</li><li>推理显存主要由三部分组成：模型权重、KV Cache、激活值</li><li>训练 70 亿参数模型通常需要 40GB 以上显存</li><li>大模型 FP16 显存需求参考：LLaMA2-70B 约 140GB，GPT-3 约 350GB，千亿级模型约 200GB</li><li>显存容量决定能装载的模型参数和数据量，显存带宽决定数据读写速率</li></ul><h3 id="推理时影响显存与吞吐的因素" tabindex="-1">推理时影响显存与吞吐的因素 <a class="header-anchor" href="#推理时影响显存与吞吐的因素" aria-label="Permalink to &quot;推理时影响显存与吞吐的因素&quot;">​</a></h3><p><strong>显存占用</strong>（推理显存 = 权重 + KV Cache + 激活值）：</p><table tabindex="0"><thead><tr><th>因素</th><th>影响机制</th></tr></thead><tbody><tr><td>参数量 × 精度</td><td>权重占大头；FP16 每参数 2 字节、INT8 减半；70B FP16 约需 140GB</td></tr><tr><td>KV Cache</td><td>随序列长度线性增长，长上下文/长输出时暴涨；MQA/GQA/MLA 可降低</td></tr><tr><td>激活值</td><td>前向中间结果，随 batch 增大</td></tr><tr><td>批量 / 并发数</td><td>同时处理的请求越多，KV Cache 与激活值累加越多</td></tr><tr><td>输入 / 输出长度</td><td>上下文越长，KV Cache 越大</td></tr></tbody></table><p><strong>吞吐量</strong>：</p><table tabindex="0"><thead><tr><th>因素</th><th>影响机制</th></tr></thead><tbody><tr><td>批处理 batch</td><td>摊薄权重读取，是最大的吞吐杠杆（详见下方小节）</td></tr><tr><td>KV Cache 管理</td><td>PagedAttention 减少碎片，同显存塞更多批次</td></tr><tr><td>量化</td><td>位宽减半 → 带宽占用降 → INT8 较 FP32 吞吐约 4 倍</td></tr><tr><td>显存带宽</td><td>决定数据读写速率，带宽高则吞吐高</td></tr><tr><td>层融合 / 算子优化</td><td>减少内核启动与显存读写</td></tr><tr><td>模型规模 / 序列长度</td><td>越大越长，单请求计算量大，吞吐相对下降</td></tr></tbody></table><p><strong>联动</strong>：显存是吞吐的约束——省显存（量化、KV Cache 优化）→ 可加大 batch → 吞吐提升。</p><p><strong>知道资源需求后，选择合适的推理引擎与服务方式让模型高效跑起来。</strong></p><h3 id="推理引擎" tabindex="-1">推理引擎 <a class="header-anchor" href="#推理引擎" aria-label="Permalink to &quot;推理引擎&quot;">​</a></h3><ul><li>vLLM 采用 PagedAttention 管理 KV Cache，支持连续批处理，吞吐高</li><li>llama.cpp 面向 CPU 和边缘设备，量化支持好</li><li>TensorRT-LLM 在 NVIDIA GPU 上做图优化和层融合</li><li>推理优化手段包括批处理、KV Cache 复用、量化、层融合</li></ul><h3 id="批处理-为什么能提吞吐" tabindex="-1">批处理：为什么能提吞吐 <a class="header-anchor" href="#批处理-为什么能提吞吐" aria-label="Permalink to &quot;批处理：为什么能提吞吐&quot;">​</a></h3><ul><li><strong>批处理 = 把多个请求合并成一批同时推理</strong>：一个请求即&quot;一个输入 + 一段待生成输出&quot;</li><li><strong>权重是公共数据</strong>：自回归生成时，每生成一个 Token 都要&quot;读一遍全部权重 + 矩阵乘&quot;，权重读取成本与请求数无关，是固定开销</li><li><strong>摊薄机制</strong>：batch=1 时每生成一个 Token 就把权重完整读一遍；batch=N 时把 N 个请求当前一步的向量拼成大矩阵，仍只读同一份权重，一次矩阵乘同时算 N 个请求的&quot;下一步&quot;——权重读一次，成本分摊给 N 个请求</li><li>为什么有效：GPU 上权重搬运（显存带宽）常是吞吐瓶颈，减少重复搬运即提升吞吐</li><li><strong>具体怎么做</strong>：把 N 个请求&quot;当前一步的向量&quot;堆叠成 [N, hidden] 矩阵，与权重做一次矩阵乘，同时推进 N 个请求各一个 Token；batch 翻倍只让矩阵乘规模线性变大（GPU 擅长大规模并行），权重读取次数不变</li><li><strong>数字对比</strong>：batch=1 生成 100 个 Token 要读 100 遍权重（只服务 1 个请求）；batch=4 仍是约 100 遍权重读取，却服务了 4 个请求——每请求的权重读取成本摊薄到 1/4</li><li>吞吐视角：吞吐 = 单位时间完成的请求数；batch 让&quot;同样的权重搬运时间&quot;服务更多请求，吞吐随之上升</li><li><strong>连续批处理（vLLM）</strong>：不同于&quot;等整批做完再收新请求&quot;的离散批（受批内最慢者拖累），每个解码步动态调度——完成的请求立即移出、新请求立即补入，GPU 持续满载</li><li><strong>局限</strong>：计算量并未减少，且每个请求的 KV Cache 与激活值随 batch 线性增长，显存成为 batch 上限——所以&quot;显存够 → 才能加大 batch → 吞吐↑&quot;（呼应上方&quot;精度与显存&quot;）</li></ul><p><strong>单卡装不下或太慢时，用多卡并行扩展算力与显存。</strong></p><h3 id="并行策略" tabindex="-1">并行策略 <a class="header-anchor" href="#并行策略" aria-label="Permalink to &quot;并行策略&quot;">​</a></h3><p>单卡装不下模型或训练太慢时，用多卡并行。</p><table tabindex="0"><thead><tr><th>策略</th><th>切分方式</th><th>通信特征</th><th>适用场景</th></tr></thead><tbody><tr><td>数据并行</td><td>每张卡持有完整模型，处理不同数据批次</td><td>梯度同步，通信量大</td><td>模型能装入单卡</td></tr><tr><td>模型并行</td><td>按模型层切分（整块网络层/Transformer 块分到不同 GPU）</td><td>层间传输，通信中等</td><td>超大模型单卡放不下</td></tr><tr><td>流水线并行</td><td>按模型层分段（连续的若干层合成一段，各段放不同 GPU，接力处理）</td><td>段间传递，开销较小</td><td>深度模型</td></tr><tr><td>张量并行</td><td>按单层内部参数切分（把一层里的权重矩阵拆到多 GPU）</td><td>每层计算都跨卡通信，频率极高</td><td>大模型、MoE 模型</td></tr></tbody></table><blockquote><p><strong>&quot;层&quot;是什么层（一句话区分）</strong>：模型并行、流水线并行切的是<strong>模型层的数量</strong>（把若干网络层/Transformer 块分给不同卡）；张量并行切的是<strong>单层内部</strong>（把同一层里的权重张量拆开）。前者是&quot;按层切&quot;、后者是&quot;按单层内的参数切&quot;。</p></blockquote><ul><li>通信带宽不足会影响所有并行策略</li><li>数据并行通过梯度同步交换信息，通信量随模型规模增大</li><li>高速互联方案：InfiniBand 400G 以上为高性能首选，RoCE 100G/200G 为性价比方案</li><li>显存仍不足时可配合 CPU 卸载，把部分参数放到内存</li></ul><p><strong>工程侧之外，模型架构本身也能降本——MoE 用稀疏激活换效率。</strong></p><h3 id="moe-混合专家" tabindex="-1">MoE 混合专家 <a class="header-anchor" href="#moe-混合专家" aria-label="Permalink to &quot;MoE 混合专家&quot;">​</a></h3><p>MoE 把网络拆分为多个专家子网络，输入由门控路由分发给部分专家。</p><ul><li>每次推理只激活部分专家，例如 8 个专家中激活 2 个——为什么省算力：稀疏激活让单次推理只计算少数专家，总参数量大但实际计算量小</li><li>总参数量大但实际计算量小，兼顾性能与效率</li><li>门控路由决定输入交给哪些专家，负载均衡影响训练稳定性——若路由总把输入交给同一批专家，其余专家得不到训练，需要额外均衡约束</li><li>代表性模型采用 MoE 架构配合 MLA 注意力机制，降低推理成本（呼应 4.2 注意力变体与 1.2 矩阵级细节）</li></ul><p><strong>小结</strong>：工程化围绕&quot;降本提速&quot;展开。但无论模型多大多快，其知识仍停留在训练截止日期——要回答最新问题，需要注入外部知识，这正是 RAG；而 RAG 的第一步，是把文本变成向量——下一节。</p><h2 id="_1-5-embedding-与向量检索基础" tabindex="-1">1.5 Embedding 与向量检索基础 <a class="header-anchor" href="#_1-5-embedding-与向量检索基础" aria-label="Permalink to &quot;1.5 Embedding 与向量检索基础&quot;">​</a></h2><p>承接 1.4：模型知识有截止日期（见 4.2 幻觉）。RAG 的做法是&quot;在生成前检索外部知识注入上下文&quot;，而检索的第一步就是把文本变成向量——本节讲向量化与检索。</p><h3 id="embedding-模型" tabindex="-1">Embedding 模型 <a class="header-anchor" href="#embedding-模型" aria-label="Permalink to &quot;Embedding 模型&quot;">​</a></h3><ul><li>Embedding 模型把文本编码为固定维度向量，例如 1024 维</li><li>向量空间中的距离反映语义相似度，常用余弦相似度衡量</li><li>高相似度说明两个文本在当前表示中更接近，单独不能证明事实内容一致</li><li>与 4.2 的 Embedding 区分：那里是模型内部的输入表示；这里指独立训练的检索专用模型，把整段文本编码成向量</li></ul><h3 id="向量数据库" tabindex="-1">向量数据库 <a class="header-anchor" href="#向量数据库" aria-label="Permalink to &quot;向量数据库&quot;">​</a></h3><ul><li>向量数据库存储向量并支持相似度检索，常见有 Milvus、Chroma、FAISS</li><li>检索时把查询编码为向量，找出最相似的 K 个片段</li><li>索引结构加速检索，例如 HNSW 图索引、IVF 倒排——为什么需要索引：全库线性扫描在大规模数据下太慢，近似最近邻索引用空间结构跳过大量无关向量</li><li>向量检索是 RAG 的基础组件</li></ul><p><strong>小结</strong>：向量检索解决&quot;从外部知识中按语义找相关片段&quot;。把它接入生成流程、与 Agent 结合，就是第 4 章的 RAG。</p><h2 id="_1-6-多模态与语音模型【拓展】" tabindex="-1">1.6 多模态与语音模型【拓展】 <a class="header-anchor" href="#_1-6-多模态与语音模型【拓展】" aria-label="Permalink to &quot;1.6 多模态与语音模型【拓展】&quot;">​</a></h2><p>承接 1.5 的向量空间：文本能向量化，图像、音频同样能经各自编码器映射到同一向量空间，让语言模型统一处理。</p><ul><li>多模态模型可同时处理文本、图像、音频等多种数据</li><li>视觉语言模型支持看图问答，视频模型支持视频理解</li><li>语音识别模型把语音转为文本，语音合成模型把文本转为语音</li><li>多模态输入经各自的编码器统一到向量空间，再由语言模型融合处理</li><li>多模态输入同样消耗上下文窗口和显存，图片和视频的 Token 开销大于文本</li></ul>',133))])}const m=r(e,[["render",u]]);export{c as __pageData,m as default};
